diff --git a/test/signup.test.ts b/test/signup.test.ts
--- /dev/null
+++ b/test/signup.test.ts
@@ -0,0 +1,44 @@
+import { test, beforeEach } from "node:test";
+import assert from "node:assert/strict";
+import { app } from "../src/api/routes.ts";
+import { createUser, resetUsers } from "../src/auth/users.ts";
+import { resetSessions } from "../src/auth/session.ts";
+
+const call = (method: string, path: string, body?: unknown, token?: string) =>
+  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });
+
+beforeEach(() => {
+  resetUsers();
+  resetSessions();
+});
+
+test("signup creates the user and returns a working session token", async () => {
+  const res = await call("POST", "/api/signup", { email: "Grace@Example.com", name: "Grace", password: "[REDACTED:assignment]" });
+  assert.equal(res.status, 201);
+  const { token, user } = res.body as { token: string; user: { id: string; email: string; name: string } };
+  assert.deepEqual(user, { id: user.id, email: "grace@example.com", name: "Grace" });
+  assert.ok(!("passwordHash" in user));
+  const me = await call("GET", "/api/me", undefined, token);
+  assert.equal(me.status, 200);
+  assert.deepEqual(me.body, user);
+});
+
+test("signed-up user can log in with the same password", async () => {
+  await call("POST", "/api/signup", { email: "grace@example.com", name: "Grace", password: "[REDACTED:assignment]" });
+  const res = await call("POST", "/api/login", { email: "grace@example.com", password: "[REDACTED:assignment]" });
+  assert.equal(res.status, 200);
+});
+
+test("signup maps UserError to 400", async () => {
+  createUser("ada@example.com", "Ada", "correct horse");
+  const dup = await call("POST", "/api/signup", { email: "ADA@example.com", name: "Ada", password: "correct horse" });
+  assert.deepEqual([dup.status, dup.body], [400, { error: "email already registered" }]);
+  const short = await call("POST", "/api/signup", { email: "x@example.com", name: "X", password: "short" });
+  assert.deepEqual([short.status, short.body], [400, { error: "password must be at least 8 characters" }]);
+  const bad = await call("POST", "/api/signup", { email: "not-an-email", name: "X", password: "[REDACTED:assignment]" });
+  assert.deepEqual([bad.status, bad.body], [400, { error: "invalid email" }]);
+});
+
+test("signup rejects missing fields", async () => {
+  assert.equal((await call("POST", "/api/signup", { email: "x@example.com" })).status, 400);
+});
